function loadTechServ(){
  if(state.activos.length > 0 && !confirm('Esto reemplazará el análisis actual con el caso TechServ. ¿Continuar?')) return;

  state = defaultState();
  state.proyecto = {
    nombre: 'TechServ Administración – Sede electrónica',
    organizacion: 'TechServ Administración, S.L.',
    responsable: 'Equipo GRC · Clase de ISO 27001 + ENS',
    fecha: new Date().toISOString().slice(0,10)
  };
  state.apetito = 'M';

  // Activos
  const a1 = {
    id: 'ACT-001', nombre: 'Base de datos de expedientes ciudadanos',
    tipo: '[D]', descripcion: 'BBDD que contiene los expedientes administrativos de las tres Consejerías',
    valoracion: { D:8, I:9, C:9, A:8, T:8 }
  };
  const a2 = {
    id: 'ACT-002', nombre: 'Servicio web Sede Electrónica',
    tipo: '[essential.service]', descripcion: 'Portal donde los ciudadanos presentan trámites con cl@ve/certificado',
    valoracion: { D:9, I:8, C:7, A:9, T:9 }
  };
  const a3 = {
    id: 'ACT-003', nombre: 'Servidores aplicación (cluster)',
    tipo: '[HW]', descripcion: 'Cluster de servidores que aloja la sede electrónica y el backoffice',
    valoracion: { D:8, I:6, C:6, A:5, T:5 }
  };
  const a4 = {
    id: 'ACT-004', nombre: 'Personal técnico (administradores)',
    tipo: '[P]', descripcion: '3 administradores con privilegios sobre sistemas críticos',
    valoracion: { D:7, I:6, C:7, A:6, T:5 }
  };
  state.activos = [a1, a2, a3, a4];

  // Amenazas
  const amenazasData = [
    // BBDD expedientes
    { activoId:'ACT-001', codigo:'[A.11]', nombre:'Acceso no autorizado', origen:'A', prob:'M', deg:{D:0,I:50,C:100,A:0,T:30} },
    { activoId:'ACT-001', codigo:'[A.15]', nombre:'Modificación deliberada de la información', origen:'A', prob:'B', deg:{D:0,I:100,C:0,A:0,T:0} },
    { activoId:'ACT-001', codigo:'[A.18]', nombre:'Destrucción de información', origen:'A', prob:'B', deg:{D:100,I:50,C:0,A:0,T:0} },
    { activoId:'ACT-001', codigo:'[E.15]', nombre:'Alteración accidental de la información', origen:'E', prob:'M', deg:{D:0,I:60,C:0,A:0,T:0} },
    { activoId:'ACT-001', codigo:'[E.19]', nombre:'Fugas de información', origen:'E', prob:'M', deg:{D:0,I:0,C:80,A:0,T:0} },
    // Servicio Sede
    { activoId:'ACT-002', codigo:'[A.24]', nombre:'Denegación de servicio (DoS)', origen:'A', prob:'A', deg:{D:100,I:0,C:0,A:0,T:0} },
    { activoId:'ACT-002', codigo:'[A.5]', nombre:'Suplantación de la identidad', origen:'A', prob:'M', deg:{D:0,I:60,C:80,A:100,T:50} },
    { activoId:'ACT-002', codigo:'[E.24]', nombre:'Caída por agotamiento de recursos', origen:'E', prob:'M', deg:{D:80,I:0,C:0,A:0,T:0} },
    // HW Servidores
    { activoId:'ACT-003', codigo:'[I.5]', nombre:'Avería de origen físico o lógico', origen:'I', prob:'M', deg:{D:70,I:0,C:0,A:0,T:0} },
    { activoId:'ACT-003', codigo:'[I.6]', nombre:'Corte del suministro eléctrico', origen:'I', prob:'B', deg:{D:100,I:0,C:0,A:0,T:0} },
    { activoId:'ACT-003', codigo:'[A.8]', nombre:'Difusión de software dañino (malware)', origen:'A', prob:'M', deg:{D:60,I:50,C:50,A:0,T:0} },
    // Personal
    { activoId:'ACT-004', codigo:'[A.30]', nombre:'Ingeniería social', origen:'A', prob:'A', deg:{D:0,I:50,C:80,A:30,T:30} },
    { activoId:'ACT-004', codigo:'[E.7]', nombre:'Deficiencias en la organización', origen:'E', prob:'M', deg:{D:30,I:30,C:30,A:0,T:0} },
    { activoId:'ACT-004', codigo:'[E.28]', nombre:'Indisponibilidad del personal', origen:'E', prob:'B', deg:{D:50,I:0,C:0,A:0,T:0} }
  ];
  state.amenazas = amenazasData.map((a,i) => ({...a, id:'AME-'+String(i+1).padStart(3,'0')}));

  // Salvaguardas
  const salvData = [
    // Para BBDD
    { codigo:'H.AC', nombre:'Control de acceso lógico', area:'Horizontal', tipos:['PR'], madurez:'L3', reduceProb:70, reduceImp:20, amenazasCodigos:['[A.11]','[A.6]'] },
    { codigo:'H.IA', nombre:'Identificación y autenticación', area:'Horizontal', tipos:['PR'], madurez:'L3', reduceProb:60, reduceImp:10, amenazasCodigos:['[A.5]','[A.11]'] },
    { codigo:'D.A', nombre:'Copias de seguridad (backup)', area:'Datos', tipos:['RC'], madurez:'L4', reduceProb:0, reduceImp:80, amenazasCodigos:['[A.18]','[E.15]','[I.5]','[A.8]'] },
    { codigo:'D.C', nombre:'Cifrado de la información', area:'Datos', tipos:['EL','PR'], madurez:'L2', reduceProb:50, reduceImp:60, amenazasCodigos:['[A.11]','[E.19]'] },
    { codigo:'H.tools.LA', nombre:'Análisis de logs (SIEM)', area:'Horizontal', tipos:['DC','MN'], madurez:'L3', reduceProb:30, reduceImp:30, amenazasCodigos:['[A.11]','[A.15]'] },
    // Para servicio web
    { codigo:'S.www', nombre:'Protección de servicios web (WAF)', area:'Servicios', tipos:['PR','DC'], madurez:'L3', reduceProb:60, reduceImp:40, amenazasCodigos:['[A.24]','[A.5]'] },
    { codigo:'IP.SPP', nombre:'Sistema de protección perimetral (firewall)', area:'Interconexión', tipos:['PR'], madurez:'L4', reduceProb:50, reduceImp:30, amenazasCodigos:['[A.24]','[A.11]','[A.8]'] },
    // Para HW
    { codigo:'HW.A', nombre:'Aseguramiento disponibilidad HW (redundancia)', area:'Hardware', tipos:['IM','RC'], madurez:'L3', reduceProb:30, reduceImp:70, amenazasCodigos:['[I.5]','[A.24]'] },
    { codigo:'AUX.power', nombre:'Suministro eléctrico (SAI/generador)', area:'Auxiliares', tipos:['IM'], madurez:'L4', reduceProb:0, reduceImp:90, amenazasCodigos:['[I.6]'] },
    { codigo:'H.tools.AV', nombre:'Herramienta antimalware', area:'Horizontal', tipos:['PR','DC'], madurez:'L4', reduceProb:70, reduceImp:40, amenazasCodigos:['[A.8]'] },
    // Para personal
    { codigo:'PS.AT', nombre:'Formación y concienciación', area:'Personal', tipos:['AW','PR'], madurez:'L2', reduceProb:50, reduceImp:30, amenazasCodigos:['[A.30]','[E.7]','[E.15]'] },
    { codigo:'H.ST', nombre:'Segregación de tareas', area:'Horizontal', tipos:['PR'], madurez:'L2', reduceProb:40, reduceImp:30, amenazasCodigos:['[E.7]','[A.6]','[A.15]'] }
  ];
  state.salvaguardas = salvData.map((s,i) => {
    const amIds = state.amenazas.filter(am => s.amenazasCodigos.includes(am.codigo)).map(am => am.id);
    const {amenazasCodigos, ...rest} = s;
    return { ...rest, id:'SAL-'+String(i+1).padStart(3,'0'), amenazasIds: amIds };
  });

  // Tratamiento sugerido
  state.tratamiento = {};
  state.amenazas.forEach(am => {
    const act = state.activos.find(a => a.id===am.activoId);
    const res = riesgoResidual(act, am);
    const resMax = riesgoMaxNivel(res.riesgo);
    if(resMax && NIVEL_NUM[resMax] > NIVEL_NUM[state.apetito]){
      state.tratamiento[am.id] = { opcion:'mitigar', responsable:'Responsable de Seguridad', plazo:'', notas:'Reforzar salvaguardas hasta alcanzar el apetito.' };
    } else {
      state.tratamiento[am.id] = { opcion:'aceptar', responsable:'Dirección', plazo:'', notas:'Riesgo dentro del apetito declarado.' };
    }
  });

  save();
  renderAll();
  showTab('inicio');
  alert('Caso TechServ cargado. Recorre las pestañas en orden para ver el análisis completo.');
}
